package app.nyxvault;
import android.app.Activity; import android.graphics.Bitmap; import android.graphics.BitmapFactory; import android.graphics.Color; import android.os.Bundle; import android.text.TextUtils; import android.view.Gravity; import android.view.View; import android.view.ViewGroup; import android.widget.Button; import android.widget.FrameLayout; import android.widget.ImageView; import android.widget.LinearLayout; import android.widget.TextView; import androidx.annotation.Nullable; import androidx.media3.common.MediaItem; import androidx.media3.common.Player; import androidx.media3.exoplayer.ExoPlayer; import androidx.media3.ui.PlayerView; import java.io.File; import java.nio.charset.StandardCharsets;
public class NyxMediaViewerActivity extends Activity { private static final String ROOT="nyx-media",META="nyx-media.json"; private ExoPlayer player; private TextView status; private int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} private TextView text(String v,float s,int c){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);return t;} private Button action(String v){Button b=new Button(this);b.setText(v);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setBackgroundColor(Color.TRANSPARENT);b.setMinHeight(dp(42));b.setStateListAnimator(null);return b;}
@Override public void onCreate(@Nullable Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Color.rgb(9,9,9));getWindow().setNavigationBarColor(Color.rgb(9,9,9));String id=getIntent().getStringExtra("media_id");if(id==null||id.isEmpty()){finish();return;}try{render(id);}catch(Exception e){showError(e.getMessage());}}
private void render(String id)throws Exception{org.json.JSONObject meta=findMeta(id);if(meta==null)throw new Exception("Media not found");String mime=meta.optString("mime","application/octet-stream").toLowerCase();String name=meta.optString("name","Private media");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(9,9,9));root.setPadding(dp(12),dp(10),dp(12),dp(12));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);Button close=action("‹ Back");close.setOnClickListener(v->finish());bar.addView(close,new LinearLayout.LayoutParams(dp(76),dp(48)));LinearLayout titleBox=new LinearLayout(this);titleBox.setOrientation(LinearLayout.VERTICAL);titleBox.setPadding(dp(8),0,dp(8),0);TextView title=text(name,16,Color.rgb(242,242,242));title.setMaxLines(1);title.setEllipsize(TextUtils.TruncateAt.MIDDLE);titleBox.addView(title);titleBox.addView(text(kind(mime),11,Color.rgb(105,105,105)));bar.addView(titleBox,new LinearLayout.LayoutParams(0,-2,1));root.addView(bar,new LinearLayout.LayoutParams(-1,-2));FrameLayout stage=new FrameLayout(this);stage.setBackgroundColor(Color.rgb(5,5,5));TextView loading=text("Loading media…",13,Color.rgb(130,130,130));loading.setGravity(Gravity.CENTER);stage.addView(loading,new FrameLayout.LayoutParams(-1,-1));root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));status=text("Preparing…",12,Color.rgb(115,115,115));status.setGravity(Gravity.CENTER);root.addView(status,new LinearLayout.LayoutParams(-1,dp(34)));setContentView(root);File file=mediaFile(meta);loading.setVisibility(View.GONE);buildStage(stage,mime,file);}
private void buildStage(FrameLayout stage,String mime,File file){if(mime.startsWith("image/")){ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),opts);opts.inSampleSize=sampleSize(opts.outWidth,opts.outHeight,1600,1600);opts.inJustDecodeBounds=false;Bitmap bmp=BitmapFactory.decodeFile(file.getAbsolutePath(),opts);if(bmp==null){status.setText("This image format could not be decoded");return;}image.setImageBitmap(bmp);stage.addView(image,new FrameLayout.LayoutParams(-1,-1));status.setText("IMAGE  •  "+human(file.length()));return;}if(mime.startsWith("video/")||mime.startsWith("audio/")){PlayerView pv=new PlayerView(this);pv.setUseController(true);pv.setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING);pv.setBackgroundColor(Color.rgb(5,5,5));stage.addView(pv,new FrameLayout.LayoutParams(-1,-1));player=new ExoPlayer.Builder(this).build();pv.setPlayer(player);player.setMediaItem(MediaItem.fromUri(android.net.Uri.fromFile(file)));player.prepare();player.setPlayWhenReady(false);player.addListener(new Player.Listener(){@Override public void onPlaybackStateChanged(int state){if(state==Player.STATE_READY)status.setText(kind(mime)+"  •  "+human(file.length()));else if(state==Player.STATE_BUFFERING)status.setText("Loading…");}@Override public void onPlayerError(androidx.media3.common.PlaybackException error){status.setText("Playback error: "+error.getErrorCodeName());}});return;}TextView u=text("This media format isn't supported in NYX yet.\n\n"+mime,14,Color.LTGRAY);u.setGravity(Gravity.CENTER);stage.addView(u,new FrameLayout.LayoutParams(-1,-1));}
private int sampleSize(int w,int h,int maxW,int maxH){int s=1;while(w/(s*2)>=maxW&&h/(s*2)>=maxH)s*=2;return s;}private String kind(String m){if(m.startsWith("image/"))return"IMAGE";if(m.startsWith("video/"))return"VIDEO";if(m.startsWith("audio/"))return"AUDIO";return"MEDIA";}private String human(long b){if(b<1024)return b+" B";if(b<1048576)return(b/1024)+" KB";return String.format(java.util.Locale.US,"%.1f MB",b/1048576.0);}private void showError(String m){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setBackgroundColor(Color.rgb(9,9,9));TextView t=text(m==null?"Could not open media":m,15,Color.LTGRAY);t.setGravity(Gravity.CENTER);r.addView(t,new LinearLayout.LayoutParams(-1,-2));Button b=action("Close");b.setOnClickListener(v->finish());r.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));setContentView(r);}private org.json.JSONObject findMeta(String id)throws Exception{File f=new File(new File(getFilesDir(),ROOT),META);if(!f.exists())return null;String s=readText(f);for(String x:s.split("\\n")){if(x.trim().isEmpty())continue;org.json.JSONObject o=new org.json.JSONObject(x);if(id.equals(o.optString("id")))return o;}return null;}private File mediaFile(org.json.JSONObject meta)throws Exception{String path=meta.optString("path","");if(!path.isEmpty()){File f=new File(path);if(f.exists())return f;}throw new Exception("Media file is missing");}private String readText(File f)throws Exception{try(InputStream in=new java.io.FileInputStream(f);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString(StandardCharsets.UTF_8.name());}}@Override protected void onDestroy(){if(player!=null){player.release();player=null;}super.onDestroy();}}
